import{_ as i,C as p,o as r,c as o,j as t,a as l,E as s,a6 as n}from"./chunks/framework.CnPv4DE1.js";const k=JSON.parse('{"title":"这一个决定将决定你人生的大部分走向","description":"","frontmatter":{"title":"这一个决定将决定你人生的大部分走向","originalTitle":"This single decision will determine most of your life","date":"2025-06-23","originalUrl":"https://thedankoe.com/letters/this-single-decision-will-determine-most-of-your-life/","minutes":7,"sourceHash":"5856e4c65dcaaee8eb4d8e5f271e020a3531b6e65324bab5b1072e44742e1738","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/this-single-decision-will-determine-most-of-your-life/"}]]},"headers":[],"relativePath":"letters/this-single-decision-will-determine-most-of-your-life.md","filePath":"letters/this-single-decision-will-determine-most-of-your-life.md"}'),h={name:"letters/this-single-decision-will-determine-most-of-your-life.md"};function d(c,e,m,f,u,b){const a=p("ArticleMeta");return r(),o("div",null,[e[0]||(e[0]=t("h1",{id:"这一个决定将决定你人生的大部分走向",tabindex:"-1"},[l("这一个决定将决定你人生的大部分走向 "),t("a",{class:"header-anchor",href:"#这一个决定将决定你人生的大部分走向","aria-label":'Permalink to "这一个决定将决定你人生的大部分走向"'},"​")],-1)),s(a),e[1]||(e[1]=n('<p>决策的质量决定了你人生的质量。</p><p>但有一个决定,决定了所有其他决定。</p><p>对我自己来说,我在很小的时候就做出了这个元决定。我记不清确切是什么时候——从我10到12岁起它就一直在我脑子里——但确实有一个明确的时刻,我知道默认的人生不适合我。我用整个身心厌恶它。</p><p>我做出的最重要的单一决定,就是不整天为自己憎恨的事情工作,只换来一份微薄得可怜的薪水,同时对着电视大喊政治和体育。不让我所有的时间都被工作吸干,精力被我没有选择的任务耗尽,金钱消失在我甚至不知道自己得付的账单里。</p><p>很多人毁掉了自己的人生,因为他们做不出这个决定,更别说任何决定了。普通人是犹豫不决的,而他们并没有意识到这有多大的问题。</p><h3 id="你正朝着错误的方向疾驰" tabindex="-1">你正朝着错误的方向疾驰 <a class="header-anchor" href="#你正朝着错误的方向疾驰" aria-label="Permalink to &quot;你正朝着错误的方向疾驰&quot;">​</a></h3><p>当你出生时,你就被放上了默认的道路。</p><p>就像一列货运火车,沿着几代人铺设的混杂轨道疾驰。等你度过十几岁的年纪时,你已经积累了20年的惯性。生存模式已经在你脑中固化。programming(编程式的思维模式)影响着你的决定。问题是,这是一套非常基础的人生操作系统。上学,找工作,退休。这没有任何了不起的地方。除非你做出一个大胆而刻意的决定去转换轨道,否则你永远不会达到你的潜力。</p><p>所有决定中最重要的那个,就是拒绝默认的道路。</p><p>响应冒险的召唤。终于开始写下第一章。离开新手教程,开始第一关。</p><p>那才是<em>你的</em>人生真正开始的时刻。</p><p>你人生的结果,是由一系列10到12个大胆的决定所决定的。十几次轨道转换。而如果你不做出这些转变,你就会陷在一个乏味的人生里。你会停滞不前。这就是现代生活中巨大的陷阱。</p><p>想象你正处于一份你厌恶的工作中。</p><p>你可以决定再也不忍受这种情况,或者你可以继续犹豫不决,然后两年后醒来发现自己的人生毫无改变。事实上,那段时间里情况可能已经变得更糟了。</p><p>犹豫不决的问题在于,当你不做决定时,你就让别人来为你做决定。这就是人生。你必须<em>做</em>点什么。你每天都必须朝某个方向移动,但大多数人无法掌控这个方向。</p><p>我们把这称为“空转状态”——你的大脑处于开机且能运转的状态,但没有处理任何有意义的东西。你在做事,但你并没有真正在做什么。你厌恶它,但还没有厌恶到足以改变它的程度。</p><h3 id="你在悄悄地珍视平庸" tabindex="-1">你在悄悄地珍视平庸 <a class="header-anchor" href="#你在悄悄地珍视平庸" aria-label="Permalink to &quot;你在悄悄地珍视平庸&quot;">​</a></h3><p>你的决定揭示了你的价值观。</p><p>无论你多么想认为自己拥有高尚的价值观,我都想让你深入审视一下<em>你实际在做的事情。</em></p><p>如果你每个周末都出去玩,那你重视的是社会地位。如果你每晚都点外卖然后打开Netflix,那你重视的是舒适。如果你在打一份工,那你重视的是安全感。</p><p>价值观揭示了对你而言重要的东西。美好的人生源于把力量集中投向正确的价值观。你重视地位、舒适或安全感,这完全没问题,但要对自己坦诚。你的<em>大部分</em>精力都流向了哪里?流向了什么价值观?你把哪些资源投向了更好的人生,如果有的话?</p><p>大多数人正在把时间、精力和金钱白白倾倒。他们本可以用来创造更好人生的“货币”,一出现就消失了。多年后他们会回顾过去(这是骗人的话……很多人从不自我反思),意识到即便自己感到疲惫,几近崩溃,却什么有意义的事都没完成。</p><p>如果你想改变人生的轨迹,你需要对这个事实感到厌恶。你需要残酷地意识到,你所做的几乎每件事都在被浪费。你需要让这种痛楚深入骨髓,同时在脑中同时held住你的负面潜力和正面潜力,然后眼看着正面的那一面胜出。</p><h3 id="静下心来思考这个问题" tabindex="-1">静下心来思考这个问题 <a class="header-anchor" href="#静下心来思考这个问题" aria-label="Permalink to &quot;静下心来思考这个问题&quot;">​</a></h3><p>花接下来的7天时间,只思考这一个问题:</p><p>如果我一直做出同样的决定,我的人生最终会走向哪里?</p><p>很可能,你得出的答案并不好看。</p><p>为了让这一点更加具体,拿出一张纸。现在就做。别因为你只是在浪费时间读某个网络“智者”的文字而忽略它。然后,把你今天做的每一个动作都写下来,再写下你这一周里将重复做的所有其他日常动作。</p><p>为了更进一步,去一个公共场所。一家杂货店。一家快餐店。一个充满普通人的地方。就是去观察。看着他们。虽然我确信他们都是善良的人,但你想变成他们那样吗?你想拥有那种眼神死气沉沉的样子吗?那种缓慢而疲惫的步态?尽管你很想说服自己不是这样,但如果你继续犹豫不决,这就是你正走向的人生。</p><p>这可能需要7天,也可能需要365天,但只要你观察得足够久,并对自己真正坦诚,你就别无选择,只能彻底改变影响你决策的价值观。</p><p>通过观察大众这个简单的行为,你会意识到,有意识的健康、事业和自我实现是不可讨价还价的。</p><h3 id="没有犯错的人生就是死亡" tabindex="-1">没有犯错的人生就是死亡 <a class="header-anchor" href="#没有犯错的人生就是死亡" aria-label="Permalink to &quot;没有犯错的人生就是死亡&quot;">​</a></h3><p>错误的决定也胜过不做决定。</p><p>但要做的决定实在太多了。</p><p>你应该专注于事业还是修炼灵性?你应该学编程还是学营销?你应该寻找自己的人生目标还是寻找伴侣?你应该吃肉食饮食还是糖类饮食?</p><p>我们正处于历史上一个奇怪的节点:改变人生的选项从未如此之多,多到让你不堪重负,以至于什么都不选。</p><p>现实是,你选哪个选项并不重要,只要你选一个就行,即便结果是灾难性的。选择变得果断,意味着你不是做一个决定就算了。相反,你会在更强的觉知中持续做出决定。</p><p>在我的人生中,我做过一系列的决定,别人可能会觉得那些是愚蠢、疯狂或不值得做的。</p><p>差不多5年前,我睡在一间客房的地垫上,因为我不想花钱搬出前女友的住处。我当时很节俭,过分节省。那时我在做我的副业,然后我决定说一句“他妈的,不管了”,把除了一袋衣服之外拥有的所有东西都扔掉,和一个我在网上认识的朋友搬去了墨西哥。</p><p>两周后,我感觉自己犯下了人生中最大的错误。我很讨厌那里。天堂糟透了。我需要一个稳定的落脚点。我的事业当时刚开始有起色,而在Playa Del Carmen那种充满干扰的地方,我根本无法把它做大。</p><p>于是我做出了另一个决定。我给我在亚利桑那的朋友打电话,问他要不要和我一起租个公寓。而不是随便什么公寓,这是一个租金比我人生中租过的任何地方都贵两倍的地方。我很自信,自己就是那种能在如此巨大的压力下把事业做起来的人。</p><p>结果那12个月,是我人生中成长最多的一段时间。我从未如此精瘦、平静、财务稳定,也从未如此有活力。凭借2个大胆的决定,我的人生发生了彻底的改变。我成了一个完全不同的人。</p><p>到那时,我已经见识到犯错的巨大力量。见识到弄清自己在人生中不想要什么的巨大力量。任何“疯狂”的想法都不再疯狂,它成了任何美好事物在人生中出现的催化剂。搬到另一个国家?这是个大风险,但如果你是一个果断的人,你随时可以搬回去,因为你可以决定提升自己的技能、赚更多的钱。果断会改变你对可能性的认知。</p><p>当那份公寓租约到期时,我和我现在的编辑搬去了德克萨斯州,和Dakota Robertson以及JK Molina住在一起——他们是我在Twitter上认识的朋友。当Dakota因为签证问题在6个月后不得不离开时,那才是“错误”真正开始发挥作用的时候。</p><p>我们搬回亚利桑那,租了一个更贵的地方。一年后,我买下了我的第一套房子,而且又一次深深地后悔了。但这次亏损的是110万美元,而不是几千美元。我不想在人生这么早的阶段就被固定住。我甚至根本不想住在那个地方。两个月后,我把那套公寓重新挂牌出售。谢天谢地,一切结束后我只亏了大约十万美元。很痛,但非常值得,因为我获得了无价的清晰认知——我到底想要什么。</p><p>这仅仅是我犯错的开始。我现在正处于另一个巨大的“错误”当中。这一次的代价是300万美元,但那就是获得清晰认知的成本,而这种清晰认知能在极短的时间内把这一切都赚回来。</p><p>你做出的大胆决定越多,你犯的错误就越多,这会带来更多的经验,确保每一个决定所造成的错误随着时间推移影响越来越小,像一枚制导导弹一样,把你精准地引向成功。</p><p>没有犯错的人生就是死亡。</p><p>当你准备好的时候,以下是我能进一步帮助你的方式:</p><ul><li>完整的一人企业启动课程现已在<a href="https://letters.thedankoe.com/p/full-course-the-one-person-business" target="_blank" rel="noreferrer">本Substack的付费版本</a>上线</li><li>在这里阅读上一篇文章<a href="https://letters.thedankoe.com/p/the-death-of-thoughtful-creation" target="_blank" rel="noreferrer">《深思创造的死亡》</a></li><li>观看我最新的YouTube视频,了解<a href="https://youtu.be/JGlx6norGpM" target="_blank" rel="noreferrer">如何成为你人生的主角</a></li></ul><hr><p><a href="/en/letters/this-single-decision-will-determine-most-of-your-life">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',52))])}const g=i(h,[["render",d]]);export{k as __pageData,g as default};
